"use client";

import React from "react";
import { useStableId } from "../hooks/useStableId";
import { Field } from "./Field";
import styles from "./Select.module.css";

export interface SelectIcon {
  id: string;
  label: string;
  icon: React.ReactNode;
}
export interface SelectOption {
  value: string;
  label: string;
  disabled?: boolean;
  icons?: readonly SelectIcon[];
}
export interface SelectProps
  extends React.SelectHTMLAttributes<HTMLSelectElement> {
  label?: string;
  labelStyle?: "plain" | "notch";
  variant?: "default" | "long" | "full";
  options?: readonly SelectOption[];
  helperText?: string;
  error?: string;
  /** Show decorative icons associated with the selected option. */
  iconStack?: boolean;
  onValueChange?: (value: string) => void;
  placeholder?: string;
  /** className applies to the field; controlClassName applies to the native select. */
  controlClassName?: string;
}

/** Native selection, with optional cut label and selected-option icon stack. */
export function Select({
  label,
  labelStyle = "plain",
  variant = "default",
  options = [],
  helperText,
  error,
  iconStack = false,
  onValueChange,
  placeholder,
  className = "",
  controlClassName = "",
  id,
  value,
  defaultValue,
  onChange,
  children,
  style,
  "aria-describedby": describedBy,
  "aria-invalid": invalid,
  ...props
}: SelectProps) {
  const selectId = useStableId("select", id);
  const ref = React.useRef<HTMLSelectElement>(null);
  const [internalValue, setInternalValue] = React.useState(
    String(
      defaultValue ?? options.find((option) => !option.disabled)?.value ?? "",
    ),
  );
  const selectedValue = value === undefined ? internalValue : String(value);
  const icons = iconStack && !props.multiple
    ? (options.find((option) => option.value === selectedValue)?.icons ?? [])
    : [];
  React.useLayoutEffect(() => {
    const select = ref.current;
    if (!select || value !== undefined) return;
    const sync = () => setInternalValue(select.value);
    sync();
    const form = select.form;
    const reset = () => queueMicrotask(sync);
    form?.addEventListener("reset", reset);
    return () => form?.removeEventListener("reset", reset);
  }, [value, options, children]);
  return (
    <Field
      id={selectId}
      label={label}
      labelStyle={labelStyle}
      helperText={helperText}
      error={error}
      describedBy={describedBy}
      invalid={invalid}
      className={className}
      style={
        {
          "--field-width":
            variant === "full"
              ? "100%"
              : variant === "long"
                ? "360px"
                : "240px",
          ...style,
        } as React.CSSProperties
      }
    >
      {(attributes) => (
        <>
          <select
            {...props}
            {...attributes}
            ref={ref}
            id={selectId}
            value={value}
            defaultValue={defaultValue}
            className={`${styles.select} ${controlClassName}`.trim()}
            style={
              {
                "--select-stack-width": `${icons.length ? 28 + (icons.length - 1) * 16 + 12 : 0}px`,
              } as React.CSSProperties
            }
            onChange={(event) => {
              setInternalValue(event.target.value);
              onChange?.(event);
              onValueChange?.(event.target.value);
            }}
          >
            {placeholder && (
              <option value="" disabled>
                {placeholder}
              </option>
            )}
            {children ??
              options.map((option) => (
                <option
                  key={option.value}
                  value={option.value}
                  disabled={option.disabled}
                >
                  {option.label}
                </option>
              ))}
          </select>
          {icons.length > 0 && (
            <span className={styles.stack} aria-hidden="true">
              {icons.map((item) => (
                <span className={styles.icon} key={item.id} title={item.label}>
                  {item.icon}
                </span>
              ))}
            </span>
          )}
          <svg
            className={styles.chevron}
            aria-hidden="true"
            width="10"
            height="8"
            viewBox="0 0 10 8"
            fill="none"
          >
            <path
              d="m1 2 4 4 4-4"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </>
      )}
    </Field>
  );
}

.select {
  display: block;
  box-sizing: border-box;
  width: 100%;
  min-height: 44px;
  border: 0;
  outline: none;
  border-radius: inherit;
  background: transparent;
  color: var(--text-primary);
  font: 500 1rem/1.4 var(--font-mono);
  appearance: none;
  padding: 12px calc(2.5rem + var(--select-stack-width, 0px)) 12px 12px;
  cursor: pointer;
}
.select:disabled {
  cursor: not-allowed;
}
.select option {
  background: var(--bg-primary);
  color: var(--text-primary);
}
.chevron {
  position: absolute;
  right: 1rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-secondary);
  pointer-events: none;
}
.stack {
  position: absolute;
  right: 2.5rem;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  pointer-events: none;
}
.icon {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--select-icon-background, #fff);
  border: 1px solid var(--color-border-default);
  overflow: hidden;
}
.icon + .icon {
  margin-left: -12px;
}
.icon > * {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

@supports (appearance: base-select) {
  .select:not([multiple]):not([size]), .select:not([multiple]):not([size])::picker(select) { appearance: base-select; }
  .select::picker-icon { display: none; }
  .select::picker(select) {
    margin-top: 6px; padding: 4px; border: 1px solid var(--color-border-default);
    border-radius: var(--field-radius, 6px); background: var(--field-background, var(--color-bg-tile)); color: var(--text-primary);
    font: 500 1rem/1.4 var(--font-mono); max-height: 320px; overflow-y: auto;
  }
  .select option { padding: 10px 12px; border-radius: 2px; cursor: pointer; justify-content: flex-start; text-align: left; background: transparent; }
  .select option:hover, .select option:focus { background: var(--interactive-secondary-bg); outline: none; }
  .select option:checked { color: var(--color-accent); }
  .select option:disabled { opacity: .45; cursor: not-allowed; }
  .select option::checkmark { order: 1; margin-left: auto; }
}
